{
  "score": 8,
  "findings": [
    {
      "file": "core/pipeline/runner.sh",
      "category": "hot-path inefficiency",
      "severity": "low",
      "line": 3911,
      "message": "In the dispatch-unit loop, `resume_mode` is never cleared after the interrupted stage is found and dispatched, so `get_state_field` (which calls `validate_json` → jq + a second jq field read = 2 subprocesses) fires for every remaining dispatch unit in the loop, even though those subsequent stages cannot be `complete`; for a pipeline with n stages after the interruption point this spawns O(2n) unnecessary jq processes on the hot path.",
      "quote": "if $resume_mode && [[ -z \"$skip_until_stage\" ]]; then\n                        local _du_stage_status\n                        # Sanitize stage id to prevent jq injection via template-sourced values.\n                        local _safe_ust=\"${_ust//[^a-zA-Z0-9_-]/}\"\n                        _du_stage_status=\"$(get_state_field \"$state_file\" \\\n                            \".stage_statuses[\\\"$_safe_ust\\\"]\" '' 2>/dev/null || true)\"",
      "introduced": true,
      "fix": "code"
    }
  ]
}
